-- طبق قانون CLAUDE.md (تایید‌شده زنده): رشتهٔ پیوستهٔ entity به‌صورت literal داخل gsub باعث خطای
-- ذخیره‌سازی command توسط سرور Teamyar می‌شود؛ با Concatenation ساخته می‌شود.
local AMP_ENTITY = "&" .. "amp;"
local LT_ENTITY = "&" .. "lt;"
local GT_ENTITY = "&" .. "gt;"
local QUOT_ENTITY = "&" .. "quot;"
local APOS_ENTITY = "&" .. "#39;"

local function escape_html(value)
    if value == nil then return "" end
    return tostring(value)
        :gsub("&", AMP_ENTITY)
        :gsub("<", LT_ENTITY)
        :gsub(">", GT_ENTITY)
        :gsub('"', QUOT_ENTITY)
        :gsub("'", APOS_ENTITY)
end

local function js_str(value)
    local s = tostring(value or "")
    return (s:gsub("\\", "\\\\"):gsub("'", "\\'"):gsub("\n", " "):gsub("\r", ""))
end

local function fmt_num(value)
    local n = tonumber(value)
    if n == nil then return "0" end
    local sign = ""
    if n < 0 then sign = "-"; n = -n end
    local s = tostring(math.floor(n + 0.5))
    return sign .. s:reverse():gsub("(%d%d%d)", "%1,"):reverse():gsub("^,", "")
end

local function fmt_dec1(value)
    local n = tonumber(value)
    if n == nil then return "0.0" end
    return string.format("%.1f", n)
end

local function fmt_pct(part, total)
    local t = tonumber(total) or 0
    if t <= 0 then return 0.0 end
    return (tonumber(part) or 0) / t * 100.0
end

local function safe_str(v, default_v)
    if v == nil or v == "" then return default_v or "—" end
    return tostring(v)
end

-- مدت‌زمان به ساعت:دقیقه:ثانیه (ورودی: ثانیه)
local function fmt_duration(total_seconds)
    local s = math.floor(tonumber(total_seconds) or 0)
    if s < 0 then s = 0 end
    local h = math.floor(s / 3600)
    local m = math.floor((s % 3600) / 60)
    local sec = s % 60
    return string.format("%02d:%02d:%02d", h, m, sec)
end

local function dialstatus_label(code)
    local n = tonumber(code)
    if n == nil then return "نامشخص" end
    return CONFIG.DIALSTATUS_LABELS[n] or ("نامشخص (کد " .. tostring(n) .. ")")
end

-- ============================================================
-- DATE HELPERS — کاملاً سمت Lua (بدون وابستگی به REPORT_FN_JDATE)، عیناً از
-- action_management_dashboard_report_bot.lua کپی‌شده (طبق قانون این ریپو: کپی/تایید، نه بازنویسی)
-- ============================================================

local function days_from_civil(y, m, d)
    if m <= 2 then y = y - 1 end
    local era
    if y >= 0 then era = math.floor(y / 400) else era = math.floor((y - 399) / 400) end
    local yoe = y - era * 400
    local mm = m + (m > 2 and -3 or 9)
    local doy = math.floor((153 * mm + 2) / 5) + d - 1
    local doe = yoe * 365 + math.floor(yoe / 4) - math.floor(yoe / 100) + doy
    return era * 146097 + doe - 719468
end

local function civil_from_civil_days(z)
    z = z + 719468
    local era
    if z >= 0 then era = math.floor(z / 146097) else era = math.floor((z - 146096) / 146097) end
    local doe = z - era * 146097
    local yoe = math.floor((doe - math.floor(doe / 1460) + math.floor(doe / 36524) - math.floor(doe / 146096)) / 365)
    local y = yoe + era * 400
    local doy = doe - (365 * yoe + math.floor(yoe / 4) - math.floor(yoe / 100))
    local mp = math.floor((5 * doy + 2) / 153)
    local d = doy - math.floor((153 * mp + 2) / 5) + 1
    local m = mp + ((mp < 10) and 3 or (-9))
    y = y + ((m <= 2) and 1 or 0)
    return y, m, d
end

local function gregorian_to_jalali(gy, gm, gd)
    local g_days_in_month = { 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31 }
    local gy2 = (gm > 2) and (gy + 1) or gy
    local days = 355666 + (365 * gy) + math.floor((gy2 + 3) / 4) - math.floor((gy2 + 99) / 100) +
        math.floor((gy2 + 399) / 400) + gd
    for i = 1, gm - 1 do days = days + g_days_in_month[i] end

    local jy = -1595 + (33 * math.floor(days / 12053))
    days = days % 12053
    jy = jy + 4 * math.floor(days / 1461)
    days = days % 1461
    if days > 365 then
        jy = jy + math.floor((days - 1) / 365)
        days = (days - 1) % 365
    end

    local jm, jd
    if days < 186 then
        jm = 1 + math.floor(days / 31)
        jd = 1 + (days % 31)
    else
        jm = 7 + math.floor((days - 186) / 30)
        jd = 1 + ((days - 186) % 30)
    end
    return jy, jm, jd
end

local function jalali_to_gregorian(jy, jm, jd)
    jy = jy + 1595
    local days = -355668 + (365 * jy) + (math.floor(jy / 33) * 8) + math.floor(((jy % 33) + 3) / 4) + jd
    if jm < 7 then
        days = days + (jm - 1) * 31
    else
        days = days + ((jm - 7) * 30) + 186
    end

    local gy = 400 * math.floor(days / 146097)
    days = days % 146097
    if days > 36524 then
        days = days - 1
        gy = gy + 100 * math.floor(days / 36524)
        days = days % 36524
        if days >= 365 then days = days + 1 end
    end
    gy = gy + 4 * math.floor(days / 1461)
    days = days % 1461
    if days > 365 then
        gy = gy + math.floor((days - 1) / 365)
        days = (days - 1) % 365
    end
    local gd = days + 1

    local is_leap = (gy % 4 == 0 and gy % 100 ~= 0) or (gy % 400 == 0)
    local g_days_in_month = { 31, is_leap and 29 or 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31 }
    local gm = 1
    while gm <= 12 and gd > g_days_in_month[gm] do
        gd = gd - g_days_in_month[gm]
        gm = gm + 1
    end
    return gy, gm, gd
end

local function jalali_to_filetime(jy, jm, jd)
    if jy == nil or jm == nil or jd == nil then return nil end
    local gy, gm, gd = jalali_to_gregorian(jy, jm, jd)
    local days = days_from_civil(gy, gm, gd)
    local unix_seconds = days * 86400
    return (unix_seconds + 11644473600) * 10000000
end

local function filetime_to_jalali(raw)
    raw = tonumber(raw)
    if raw == nil or raw <= 0 then return nil end
    local unix_seconds = raw / 10000000 - 11644473600
    local days = math.floor(unix_seconds / 86400)
    local gy, gm, gd = civil_from_civil_days(days)
    local jy, jm, jd = gregorian_to_jalali(gy, gm, gd)
    return { y = jy, m = jm, d = jd }
end

-- امروز شمسی (برای پیش‌فرض فیلتر و محدودهٔ Dropdown سال)
local now_raw = tonumber(string.format("%18.0f", time.get_filetime(string.format(
    '{"year":%d,"month":%d,"day":%d,"hour":0,"minute":0,"second":0}',
    time.get_year(time.current()), time.get_month(time.current()), time.get_day(time.current())))))
local today_j = filetime_to_jalali(now_raw) or { y = 1404, m = 1, d = 1 }

-- ============================================================
-- DATABASE HELPERS
-- ============================================================

local function fetch_rows(query, params)
    pcall(function() db.use_db("0000000") end)
    local ok, err = pcall(function()
        db.query({ query = query, params = params or {} })
    end)
    if not ok then return nil, err end
    local rows = {}
    local record = {}
    while db.query_fetch(record) do
        local row = {}
        for i = 1, #record do row[i] = record[i] end
        table.insert(rows, row)
    end
    db.query_free()
    return rows
end

-- ============================================================
-- FILTER PARSER — سه Dropdown شمسی روز/ماه/سال برای از/تا (نه <input type=date> میلادی)
-- ============================================================

local function jalali_ymd_from_input(inp, prefix)
    local y = tonumber(inp[prefix .. "_jy"])
    local m = tonumber(inp[prefix .. "_jm"])
    local d = tonumber(inp[prefix .. "_jd"])
    if y == nil or m == nil or d == nil then return nil, nil, nil end
    return y, m, d
end

local function parse_filters(inp)
    inp = inp or {}
    local from_jy, from_jm, from_jd = jalali_ymd_from_input(inp, "from")
    local to_jy, to_jm, to_jd = jalali_ymd_from_input(inp, "to")

    local from_raw = jalali_to_filetime(from_jy, from_jm, from_jd)
    local to_raw = jalali_to_filetime(to_jy, to_jm, to_jd)

    if to_raw == nil then
        to_raw = now_raw
        to_jy, to_jm, to_jd = today_j.y, today_j.m, today_j.d
    end
    if from_raw == nil then
        from_raw = to_raw - (CONFIG.DEFAULT_RANGE_DAYS * CONFIG.DAY_TICKS)
        local fj = filetime_to_jalali(from_raw)
        from_jy, from_jm, from_jd = fj.y, fj.m, fj.d
    end
    -- انتهای بازهٔ «تا» شامل کل همان روز شود (تا پایان ۲۳:۵۹:۵۹)
    local to_raw_inclusive = to_raw + CONFIG.DAY_TICKS - 1

    return {
        from_raw = from_raw, to_raw = to_raw_inclusive,
        from_jy = from_jy, from_jm = from_jm, from_jd = from_jd,
        to_jy = to_jy, to_jm = to_jm, to_jd = to_jd,
    }
end

local filters = parse_filters(input)

-- ============================================================
-- SQL — منبع مشترک (زنده + آرشیو)، فقط ستون‌های لازم (نه SELECT *)
-- ============================================================

local VOIP_UNION = [[
(
  SELECT linkedid, Date, DialStatus, Duration, CallerProfileID, ConnectedLineProfileID
  FROM voip_calls
  WHERE Date BETWEEN ? AND ? AND linkedid <> 0
  UNION ALL
  SELECT linkedid, Date, DialStatus, Duration, CallerProfileID, ConnectedLineProfileID
  FROM `0000000_archive`.voip_calls
  WHERE Date BETWEEN ? AND ? AND linkedid <> 0
) v
]]

-- CONFIG.EXCLUDED_AGENT_IDS -> رشتهٔ عددی امن برای NOT IN (اعتبارسنجی با tonumber/math.floor — این
-- فهرست از کانفیگ ثابت می‌آید نه از ورودی کاربر، اما بازهم عددی‌سازی می‌شود تا تضمینی باشد؛ وقتی خالی
-- است "(0)" می‌دهد که بی‌اثر است چون ID=0 هیچ‌وقت واقعی نیست)
local function excluded_ids_sql()
    local ids = {}
    for _, id in ipairs(CONFIG.EXCLUDED_AGENT_IDS) do
        local n = tonumber(id)
        if n ~= nil then table.insert(ids, tostring(math.floor(n))) end
    end
    if #ids == 0 then return "(0)" end
    return "(" .. table.concat(ids, ",") .. ")"
end
local EXCLUDED_IDS_SQL = excluded_ids_sql()
local AGENT_SUBQ = "(SELECT ID FROM profile_main WHERE TYPE = " .. CONFIG.AGENT_TYPE ..
    " AND ID NOT IN " .. EXCLUDED_IDS_SQL .. ")"

local function date_params()
    return { filters.from_raw, filters.to_raw, filters.from_raw, filters.to_raw }
end

-- ── KPI کلی سازمان ──────────────────────────────────────────────────────
-- توجه (فیدبک مدیر کال‌سنتر): تماس داخلی (کارمند↔کارمند، هر دو سمت profile_main.TYPE=1) باید از
-- «ورودی»/«خروجی» (که باید فقط ترافیک واقعی با مشتری/بیرون باشد) جدا شود، نه با آن‌ها جمع/همپوشان.
-- Outbound خالص = کارمند تماس‌گیرنده و سمت مقابل کارمند نیست. Inbound خالص = برعکس. Internal = هر دو کارمند.
local function fetch_kpi()
    local rows, err = fetch_rows(string.format([[
SELECT
    COUNT(DISTINCT v.linkedid) AS total_calls,
    COUNT(DISTINCT CASE WHEN v.DialStatus = 5 THEN v.linkedid END) AS answered,
    COUNT(DISTINCT CASE WHEN v.DialStatus = 3 THEN v.linkedid END) AS no_answer,
    COUNT(DISTINCT CASE WHEN v.DialStatus = 4 THEN v.linkedid END) AS busy,
    COUNT(DISTINCT CASE WHEN v.DialStatus = 6 THEN v.linkedid END) AS cancel,
    COUNT(DISTINCT CASE WHEN v.DialStatus NOT IN (3,4,5,6) THEN v.linkedid END) AS other_status,
    COUNT(DISTINCT CASE WHEN v.CallerProfileID IN %s AND v.ConnectedLineProfileID NOT IN %s THEN v.linkedid END) AS outbound_calls,
    COUNT(DISTINCT CASE WHEN v.ConnectedLineProfileID IN %s AND v.CallerProfileID NOT IN %s THEN v.linkedid END) AS inbound_calls,
    COUNT(DISTINCT CASE WHEN v.CallerProfileID IN %s AND v.ConnectedLineProfileID IN %s THEN v.linkedid END) AS internal_calls,
    COUNT(DISTINCT v.CallerProfileID) AS distinct_outbound_agents,
    COUNT(DISTINCT v.ConnectedLineProfileID) AS distinct_inbound_agents
FROM %s
]], AGENT_SUBQ, AGENT_SUBQ, AGENT_SUBQ, AGENT_SUBQ, AGENT_SUBQ, AGENT_SUBQ, VOIP_UNION), date_params())

    -- مدت کل مکالمه: فقط Leg سمت کارمند هر تماس (نه هر دو Leg — جلوگیری از دوبرابرشدن مدت)
    local dur_rows = fetch_rows(string.format([[
SELECT SUM(agent_leg.dur) FROM (
    SELECT v.linkedid, MAX(v.Duration) AS dur
    FROM %s
    WHERE v.CallerProfileID IN %s OR v.ConnectedLineProfileID IN %s
    GROUP BY v.linkedid
) agent_leg
]], VOIP_UNION, AGENT_SUBQ, AGENT_SUBQ), date_params())

    if rows == nil or #rows == 0 then
        return { total_calls = 0, answered = 0, no_answer = 0, busy = 0, cancel = 0, other_status = 0,
            outbound_calls = 0, inbound_calls = 0, internal_calls = 0,
            distinct_outbound_agents = 0, distinct_inbound_agents = 0,
            duration_sum = 0 }, err
    end
    local r = rows[1]
    local duration_sum = 0
    if dur_rows and dur_rows[1] and dur_rows[1][1] then duration_sum = tonumber(dur_rows[1][1]) or 0 end
    return {
        total_calls = tonumber(r[1]) or 0, answered = tonumber(r[2]) or 0, no_answer = tonumber(r[3]) or 0,
        busy = tonumber(r[4]) or 0, cancel = tonumber(r[5]) or 0, other_status = tonumber(r[6]) or 0,
        outbound_calls = tonumber(r[7]) or 0, inbound_calls = tonumber(r[8]) or 0, internal_calls = tonumber(r[9]) or 0,
        distinct_outbound_agents = tonumber(r[10]) or 0, distinct_inbound_agents = tonumber(r[11]) or 0,
        duration_sum = duration_sum,
    }, nil
end

-- ── روند روزانه (پاسخ/ناموفق، ورودی/خروجی) ─────────────────────────────
local function fetch_daily_trend()
    local rows, err = fetch_rows(string.format([[
SELECT rd.DATEKEY, rd.JTDAY,
    COUNT(DISTINCT CASE WHEN v.DialStatus = 5 THEN v.linkedid END) AS answered,
    COUNT(DISTINCT CASE WHEN v.DialStatus IN (3,4,6) THEN v.linkedid END) AS failed,
    COUNT(DISTINCT CASE WHEN v.CallerProfileID IN %s AND v.ConnectedLineProfileID NOT IN %s THEN v.linkedid END) AS outbound,
    COUNT(DISTINCT CASE WHEN v.ConnectedLineProfileID IN %s AND v.CallerProfileID NOT IN %s THEN v.linkedid END) AS inbound
FROM %s
LEFT JOIN report_dimdate rd ON rd.DATEKEY = v.Date - MOD(v.Date, %d)
GROUP BY rd.DATEKEY, rd.JTDAY
ORDER BY rd.DATEKEY
]], AGENT_SUBQ, AGENT_SUBQ, AGENT_SUBQ, AGENT_SUBQ, VOIP_UNION, CONFIG.DAY_TICKS), date_params())
    local out = {}
    for _, r in ipairs(rows or {}) do
        table.insert(out, {
            label = safe_str(r[2], "—"), answered = tonumber(r[3]) or 0, failed = tonumber(r[4]) or 0,
            outbound = tonumber(r[5]) or 0, inbound = tonumber(r[6]) or 0,
        })
    end
    return out, err
end

-- ── روند ساعتی (بازهٔ روز، برحسب تیک FILETIME — با آفست منطقهٔ زمانی کاربر) ─
local function fetch_hourly_trend()
    local rows, err = fetch_rows(string.format([[
SELECT MOD(FLOOR((v.Date - ?) / %d) + 24, 24) AS hour_of_day,
    COUNT(DISTINCT CASE WHEN v.DialStatus = 5 THEN v.linkedid END) AS answered,
    COUNT(DISTINCT CASE WHEN v.DialStatus IN (3,4,6) THEN v.linkedid END) AS failed
FROM %s
GROUP BY hour_of_day
ORDER BY hour_of_day
]], CONFIG.HOUR_TICKS, VOIP_UNION), { tz_ticks, filters.from_raw, filters.to_raw, filters.from_raw, filters.to_raw })
    local by_hour = {}
    for h = 0, 23 do by_hour[h] = { answered = 0, failed = 0 } end
    for _, r in ipairs(rows or {}) do
        local h = tonumber(r[1])
        if h ~= nil and by_hour[h] then
            by_hour[h].answered = tonumber(r[2]) or 0
            by_hour[h].failed = tonumber(r[3]) or 0
        end
    end
    local out = {}
    for h = 0, 23 do table.insert(out, { label = string.format("%02d", h), answered = by_hour[h].answered, failed = by_hour[h].failed }) end
    return out, err
end

-- ── رتبه‌بندی عملکردی کارمندان (خروجی + ورودی، ادغام‌شده) ──────────────
-- خروجی/ورودی هر کارمند هم فقط ترافیک واقعی (سمت مقابل کارمند نباشد) — تماس داخلی این‌جا شمرده نمی‌شود،
-- همان‌طور که در KPI کلی هم جدا شد (نگاه کنید به یادداشت بالای fetch_kpi)
local function fetch_agent_leaderboard()
    local out_rows, out_err = fetch_rows(string.format([[
SELECT v.CallerProfileID AS agent_id, pm.FULLNAME,
    COUNT(DISTINCT v.linkedid) AS calls,
    COUNT(DISTINCT CASE WHEN v.DialStatus = 5 THEN v.linkedid END) AS answered,
    SUM(v.Duration) AS duration_sum
FROM %s
INNER JOIN profile_main pm ON pm.ID = v.CallerProfileID AND pm.TYPE = %d AND pm.ID NOT IN %s
WHERE v.ConnectedLineProfileID NOT IN %s
GROUP BY v.CallerProfileID, pm.FULLNAME
]], VOIP_UNION, CONFIG.AGENT_TYPE, EXCLUDED_IDS_SQL, AGENT_SUBQ), date_params())

    local in_rows, in_err = fetch_rows(string.format([[
SELECT v.ConnectedLineProfileID AS agent_id, pm.FULLNAME,
    COUNT(DISTINCT v.linkedid) AS calls,
    COUNT(DISTINCT CASE WHEN v.DialStatus = 5 THEN v.linkedid END) AS answered,
    SUM(v.Duration) AS duration_sum
FROM %s
INNER JOIN profile_main pm ON pm.ID = v.ConnectedLineProfileID AND pm.TYPE = %d AND pm.ID NOT IN %s
WHERE v.CallerProfileID NOT IN %s
GROUP BY v.ConnectedLineProfileID, pm.FULLNAME
]], VOIP_UNION, CONFIG.AGENT_TYPE, EXCLUDED_IDS_SQL, AGENT_SUBQ), date_params())

    local by_agent = {}
    local order = {}
    local function ensure(id, name)
        if by_agent[id] == nil then
            by_agent[id] = { id = id, name = name, out_calls = 0, out_answered = 0, out_duration = 0,
                in_calls = 0, in_answered = 0, in_duration = 0 }
            table.insert(order, id)
        end
        return by_agent[id]
    end
    for _, r in ipairs(out_rows or {}) do
        local id = tonumber(r[1])
        if id ~= nil then
            local a = ensure(id, r[2])
            a.out_calls = tonumber(r[3]) or 0
            a.out_answered = tonumber(r[4]) or 0
            a.out_duration = tonumber(r[5]) or 0
        end
    end
    for _, r in ipairs(in_rows or {}) do
        local id = tonumber(r[1])
        if id ~= nil then
            local a = ensure(id, r[2])
            a.in_calls = tonumber(r[3]) or 0
            a.in_answered = tonumber(r[4]) or 0
            a.in_duration = tonumber(r[5]) or 0
        end
    end
    local list = {}
    for _, id in ipairs(order) do
        local a = by_agent[id]
        a.total_calls = a.out_calls + a.in_calls
        a.total_answered = a.out_answered + a.in_answered
        a.total_duration = a.out_duration + a.in_duration
        a.answer_rate = fmt_pct(a.total_answered, a.total_calls)
        table.insert(list, a)
    end
    table.sort(list, function(x, y) return x.total_calls > y.total_calls end)
    return list, out_err or in_err
end

