if daily_err then table.insert(error_notes, "روند روزانه: " .. escape_html(tostring(daily_err))) end
if hourly_err then table.insert(error_notes, "روند ساعتی: " .. escape_html(tostring(hourly_err))) end
if leaderboard_err then table.insert(error_notes, "رتبه‌بندی کارمندان: " .. escape_html(tostring(leaderboard_err))) end
