-- ============================================================
-- رندر — کارت‌ها/نمودار/جدول (CSS خالص، بدون کتابخانهٔ خارجی — CSP این پلتفرم CDN را بلاک می‌کند)
-- ============================================================

local function kpi_card(label, value, sub)
    return string.format(
        '<div class="card kpi"><div class="label">%s</div><div class="value">%s</div><div class="delta">%s</div></div>',
        escape_html(label), escape_html(value), escape_html(sub or ""))
end

local function bar_row(label, value, max_value, value_label)
    local pct = 0
    if max_value and max_value > 0 then pct = math.floor((value * 100 / max_value) + 0.5) end
    return string.format(
        [[<div class="bar-row"><span class="bar-label">%s</span><div class="bar-track"><div class="bar-fill" style="width:%d%%;"></div></div><span class="bar-value">%s</span></div>]],
        escape_html(label), pct, escape_html(value_label or fmt_num(value)))
end

local function shade_of_accent(index, total)
    local base_r, base_g, base_b = 0x16, 0x50, 0x9D
    local t = (total > 1) and ((index - 1) / (total - 1)) or 0
    local mix = 0.65 * t
    local r = math.floor(base_r + (255 - base_r) * mix)
    local g = math.floor(base_g + (255 - base_g) * mix)
    local b = math.floor(base_b + (255 - base_b) * mix)
    return string.format("#%02x%02x%02x", r, g, b)
end

local function build_donut(items)
    local total = 0
    for _, it in ipairs(items) do total = total + it.count end
    if total == 0 then
        return "background:#e7edf4;", '<span class="empty-msg">داده‌ای یافت نشد</span>'
    end
    local css_parts, legend_parts = {}, {}
    local acc = 0
    for i, it in ipairs(items) do
        local pct = it.count * 100 / total
        local color = shade_of_accent(i, #items)
        table.insert(css_parts, string.format("%s %.2f%% %.2f%%", color, acc, acc + pct))
        table.insert(legend_parts, string.format(
            '<span><i class="dot" style="background:%s;"></i>%s (%s٪)</span>',
            color, escape_html(it.name), fmt_dec1(pct)))
        acc = acc + pct
    end
    return "background:conic-gradient(" .. table.concat(css_parts, ",") .. ");", table.concat(legend_parts, "")
end

local function chart_bars(items)
    local maxv = 0
    for _, it in ipairs(items) do
        local total = (it.answered or it.value or 0) + (it.failed or 0)
        if total > maxv then maxv = total end
    end
    local parts = {}
    for _, it in ipairs(items) do
        if it.value ~= nil then
            local h = (maxv > 0) and math.floor((it.value * 100 / maxv) + 0.5) or 0
            if h < 2 and it.value > 0 then h = 2 end
            table.insert(parts, string.format(
                '<div class="bar-col"><div class="bar-stack" style="height:%d%%;"><div class="seg seg-a" style="height:100%%;"></div></div><span class="bar-col-label">%s</span></div>',
                h, escape_html(it.label)))
        else
            local total = (it.answered or 0) + (it.failed or 0)
            local h = (maxv > 0) and math.floor((total * 100 / maxv) + 0.5) or 0
            if h < 2 and total > 0 then h = 2 end
            local a_pct = (total > 0) and math.floor((it.answered * 100 / total) + 0.5) or 0
            table.insert(parts, string.format(
                '<div class="bar-col" title="%s: %s پاسخ / %s ناموفق"><div class="bar-stack" style="height:%d%%;"><div class="seg seg-a" style="height:%d%%;"></div><div class="seg seg-b" style="height:%d%%;"></div></div><span class="bar-col-label">%s</span></div>',
                escape_html(it.label), fmt_num(it.answered), fmt_num(it.failed), h, a_pct, 100 - a_pct, escape_html(it.label)))
        end
    end
    if #parts == 0 then return '<div class="empty-msg">داده‌ای یافت نشد</div>' end
    return table.concat(parts, "")
end

local function trend_table(rows, cols, headers)
    local thead = {}
    for _, h in ipairs(headers) do table.insert(thead, "<th>" .. escape_html(h) .. "</th>") end
    local tbody = {}
    for _, row in ipairs(rows) do
        local tds = {}
        for _, c in ipairs(cols) do
            local v = row[c]
            if type(v) == "number" then
                table.insert(tds, "<td>" .. fmt_num(v) .. "</td>")
            else
                table.insert(tds, "<td>" .. escape_html(v) .. "</td>")
            end
        end
        table.insert(tbody, "<tr>" .. table.concat(tds) .. "</tr>")
    end
    if #tbody == 0 then
        tbody = { '<tr><td colspan="' .. #headers .. '" class="empty-msg">داده‌ای یافت نشد</td></tr>' }
    end
    return string.format(
        '<table class="data-table"><thead><tr>%s</tr></thead><tbody>%s</tbody></table>',
        table.concat(thead), table.concat(tbody))
end

-- ── فیلتر از/تا (سه Dropdown شمسی) ──────────────────────────────────────

local function render_jalali_date_picker(prefix, label, j)
    local d_html = {}
    for i = 1, 31 do
        local sel = (tonumber(j.d) == i) and ' selected' or ''
        table.insert(d_html, '<option value="' .. i .. '"' .. sel .. '>' .. i .. '</option>')
    end
    local m_html = {}
    for i = 1, 12 do
        local sel = (tonumber(j.m) == i) and ' selected' or ''
        table.insert(m_html, '<option value="' .. i .. '"' .. sel .. '>' .. CONFIG.PERSIAN_MONTHS[i] .. '</option>')
    end
    local y_html = {}
    for y = today_j.y - 3, today_j.y do
        local sel = (tonumber(j.y) == y) and ' selected' or ''
        table.insert(y_html, '<option value="' .. y .. '"' .. sel .. '>' .. y .. '</option>')
    end
    return '<div class="filter-field"><label>' .. escape_html(label) .. '</label><div class="jdate-group">' ..
        '<select name="' .. prefix .. '_jd">' .. table.concat(d_html) .. '</select>' ..
        '<select name="' .. prefix .. '_jm">' .. table.concat(m_html) .. '</select>' ..
        '<select name="' .. prefix .. '_jy">' .. table.concat(y_html) .. '</select>' ..
        '</div></div>'
end

local filter_bar_html = [[
<form class="filter-bar" method="POST" action="">
  <div class="filter-grid">
    ]] .. render_jalali_date_picker("from", "از تاریخ", { y = filters.from_jy, m = filters.from_jm, d = filters.from_jd }) .. [[
    ]] .. render_jalali_date_picker("to", "تا تاریخ", { y = filters.to_jy, m = filters.to_jm, d = filters.to_jd }) .. [[
  </div>
  <div class="filter-actions">
    <button type="submit" class="btn-action">اعمال فیلتر</button>
    <button type="button" class="btn-action btn-ghost" onclick="window.location = window.location.pathname">۷ روز اخیر (پیش‌فرض)</button>
  </div>
</form>
]]

-- ── معیارهای مشتق‌شده — بدون کوئری جدید، فقط محاسبه روی دادهٔ همین بخش‌های بالا ──
-- (درخواست مدیر کال‌سنتر: کارت‌های عملیاتی بیشتر از همین دادهٔ موجود)

local answer_rate_overall = fmt_pct(kpi.answered, kpi.total_calls)

local aht_seconds = 0
if kpi.answered > 0 then aht_seconds = kpi.duration_sum / kpi.answered end

-- تماس‌هایی که نه ورودی خالص‌اند، نه خروجی خالص، نه داخلی — یعنی به هیچ اپراتوری وصل نشدند.
-- تخمینی از «رهاشده در صف»، نه یک SLA دقیق (clamp احتیاطی در برابر خطای گرد کردن)
local unassigned_calls = kpi.total_calls - kpi.inbound_calls - kpi.outbound_calls - kpi.internal_calls
if unassigned_calls < 0 then unassigned_calls = 0 end

local peak_hour_label, peak_hour_count = "—", 0
for _, h in ipairs(hourly_trend) do
    local total_h = h.answered + h.failed
    if total_h > peak_hour_count then
        peak_hour_count = total_h
        peak_hour_label = h.label .. ":00"
    end
end

local active_agent_count = #leaderboard
local avg_calls_per_agent = 0
if active_agent_count > 0 then
    avg_calls_per_agent = (kpi.inbound_calls + kpi.outbound_calls) / active_agent_count
end

