body{margin:0;background:var(--bg);color:var(--text);font-size:14px;overflow-x:hidden;max-width:100vw}

/* ── موبایل (پیش‌فرض) ── */
.header{background:var(--accent);color:#fff;padding:14px 14px 10px;position:sticky;top:0;z-index:10}
.header-top{display:flex;align-items:center;justify-content:space-between;gap:10px}
.brand{display:flex;align-items:center;gap:8px;font-size:16px;font-weight:800}
.brand img{height:24px;width:auto}
.header .sub{font-size:14px;color:#dbe6f3;margin-top:4px}
.nav{display:flex;gap:6px;overflow-x:auto;margin-top:10px;padding-bottom:2px}
.nav button{border:0;background:#ffffff22;color:#fff;padding:9px 13px;border-radius:9px;cursor:pointer;font:inherit;font-size:14px;white-space:nowrap;flex-shrink:0}
.nav button.active{background:#fff;color:var(--accent);font-weight:bold}
.main{padding:14px}
.page{display:none}.page.active{display:block}
.kpis{display:grid;grid-template-columns:1fr 1fr;gap:10px}
.card{background:var(--card);border:1px solid var(--line);border-radius:14px;padding:14px;box-shadow:0 2px 10px #00000009}
.kpi .label{font-size:14px;color:var(--muted);overflow-wrap:break-word}
.kpi .value{font-size:20px;font-weight:800;margin:6px 0;color:var(--accent);overflow-wrap:break-word}
.kpi .delta{font-size:14px;color:var(--muted);overflow-wrap:break-word}
.grid{display:grid;gap:12px;margin-top:12px}
.title{font-weight:bold;font-size:15px;margin-bottom:12px;color:var(--accent)}
.donut{width:150px;height:150px;border-radius:50%;margin:8px auto;position:relative}
.donut:after{content:"";position:absolute;inset:28px;background:#fff;border-radius:50%}
.legend{display:flex;gap:10px;justify-content:center;flex-wrap:wrap;font-size:14px;color:var(--muted);margin-top:8px}
.dot{display:inline-block;width:9px;height:9px;border-radius:50%;margin-left:5px}
.chart{height:180px;display:flex;align-items:flex-end;gap:4px;padding:10px 2px 26px;border-bottom:1px solid var(--line);position:relative;overflow-x:auto}
.bar-col{flex:1;min-width:20px;display:flex;flex-direction:column;justify-content:flex-end;height:100%;position:relative}
.bar-stack{width:100%;border-radius:4px 4px 1px 1px;overflow:hidden;display:flex;flex-direction:column-reverse}
.seg{width:100%}
.seg-a{background:var(--accent)}
.seg-b{background:#b9c8dd}
.bar-col-label{position:absolute;bottom:-22px;right:50%;transform:translateX(50%);font-size:14px;color:var(--muted);white-space:nowrap}
.legend-hint{font-size:14px;color:var(--muted);display:flex;gap:14px;justify-content:center;margin-top:22px;flex-wrap:wrap}
.legend-hint span{display:flex;align-items:center;gap:5px}
.bar-row{display:flex;align-items:center;gap:6px;margin-bottom:9px;max-width:100%}
.bar-label{width:84px;flex-shrink:0;text-align:right;font-size:13px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.bar-track{flex:1;height:20px;background:#f5f5f5;border-radius:6px;overflow:hidden;border:1px solid var(--line);min-width:24px}
.bar-fill{height:100%;background:var(--accent);border-radius:6px}
.bar-value{flex-shrink:0;text-align:left;font-size:12px;font-weight:bold;white-space:nowrap;max-width:38vw;overflow:hidden;text-overflow:ellipsis}
.table-wrap{overflow:auto;max-height:420px;border:1px solid var(--muted);border-radius:8px}
.data-table{width:auto;min-width:100%;border-collapse:collapse}
.data-table th{background:var(--accent);color:#fff;padding:10px 8px;text-align:center;font-size:15px;font-weight:bold;border:1px dashed #666;white-space:nowrap;width:1%;position:sticky;top:0;cursor:pointer;user-select:none}
.data-table th.sort-asc::after{content:' ▲'}.data-table th.sort-desc::after{content:' ▼'}
.data-table td{padding:8px;border:1px dashed #666;font-size:14px;text-align:center;white-space:nowrap}
.data-table tr:nth-child(even) td{background:#f5f5f5}
.data-table tr:hover td{background:#e8eef6}
.empty-msg{text-align:center;color:var(--muted);padding:18px;font-size:14px}
.error-box{background:#f5f5f5;border:1px solid var(--accent);color:var(--accent-dark);border-radius:8px;padding:12px 14px;font-size:14px;margin-bottom:16px}
.filter-bar{background:var(--card);border:1px solid var(--line);border-radius:14px;padding:14px;margin-bottom:14px}
.filter-grid{display:grid;grid-template-columns:1fr;gap:10px}
.filter-field label{display:block;font-size:14px;color:var(--muted);margin-bottom:5px}
.jdate-group{display:flex;gap:4px;max-width:100%}
.jdate-group select{flex:1;min-width:0;padding:8px 2px;border:1px solid var(--line);border-radius:8px;font-size:13px;font-family:inherit;background:#fff}
.filter-actions{display:flex;gap:8px;margin-top:12px;flex-wrap:wrap}
.btn-action{background:var(--accent);color:#fff;border:2px solid var(--accent);border-radius:9px;padding:9px 14px;font-size:14px;font-weight:bold;cursor:pointer;font-family:inherit}
.btn-action:hover{background:var(--accent-dark)}
.btn-ghost{background:transparent;color:var(--accent)}
.toolbar{display:flex;justify-content:flex-end;gap:8px;flex-wrap:wrap;margin-bottom:12px}
.help-overlay{display:none;position:fixed;inset:0;background:rgba(0,0,0,0.5);z-index:100;align-items:center;justify-content:center}
.help-overlay.open{display:flex}
.help-modal{background:#fff;border-radius:10px;max-width:640px;width:92%;max-height:84vh;overflow-y:auto;box-shadow:0 8px 24px rgba(0,0,0,0.3)}
.help-modal-header{display:flex;justify-content:space-between;align-items:center;background:var(--accent);color:#fff;padding:12px 16px;border-radius:10px 10px 0 0;font-size:15px;font-weight:bold;position:sticky;top:0}
.help-close{background:transparent;border:none;color:#fff;font-size:16px;cursor:pointer}
.help-modal-body{padding:16px;text-align:right;font-size:14px}
.help-modal-body p{margin:10px 0;line-height:1.8}
.help-modal-body ul{margin:6px 0 14px;padding-right:20px}
.help-modal-body li{margin:6px 0;line-height:1.7}
.footer{text-align:center;color:var(--muted);font-size:14px;margin:16px 0 6px;display:flex;align-items:center;justify-content:center;gap:8px}
.footer img{height:16px;width:auto}

/* ── تبلت / دسکتاپ کوچک (≥640px) ── */
@media(min-width:640px){
  .kpis{grid-template-columns:repeat(3,1fr)}
  .filter-grid{grid-template-columns:1fr 1fr}
}

/* ── دسکتاپ (≥1000px) ── */
@media(min-width:1000px){
  .header{padding:16px 26px 12px}
  .main{padding:22px;max-width:1300px;margin:0 auto}
  .kpis{grid-template-columns:repeat(6,1fr)}
  .grid-2{display:grid;grid-template-columns:1fr 1fr;gap:14px}
  .grid-3{display:grid;grid-template-columns:2fr 1fr;gap:14px}
  .filter-grid{grid-template-columns:1fr 1fr;max-width:520px}
  .bar-label{width:180px}
}
</style>
</head>
