<script>
function switchPage(name){
  document.querySelectorAll('.page').forEach(function(p){ p.classList.toggle('active', p.id===name); });
  document.querySelectorAll('.nav button').forEach(function(b){ b.classList.toggle('active', b.getAttribute('data-page')===name); });
}
document.querySelectorAll('.nav button').forEach(function(b){
  b.addEventListener('click', function(){ switchPage(b.getAttribute('data-page')); });
});

function toggleFullScreen(){
  if(!document.fullscreenElement){ document.documentElement.requestFullscreen && document.documentElement.requestFullscreen(); }
  else { document.exitFullscreen && document.exitFullscreen(); }
}

function csvEscapeCell(text){
  var s = String(text == null ? '' : text);
  if(/[",\n]/.test(s)){ s = '"' + s.replace(/"/g,'""') + '"'; }
  return s;
}
function downloadCsv(lines, fileName){
  var blob = new Blob(["\uFEFF" + lines.join("\r\n")], { type: 'text/csv;charset=utf-8;' });
  var url = URL.createObjectURL(blob);
  var a = document.createElement('a');
  a.href = url; a.download = fileName; document.body.appendChild(a); a.click();
  document.body.removeChild(a); URL.revokeObjectURL(url);
}
function exportAllToExcel(){
  var active = document.querySelector('.page.active');
  if(!active) return;
  var tables = active.querySelectorAll('table.data-table');
  if(tables.length === 0){ return; }
  var lines = [];
  tables.forEach(function(table, ti){
    if(ti > 0) lines.push('');
    table.querySelectorAll('tr').forEach(function(tr){
      var cells = tr.querySelectorAll('th,td');
      var row = [];
      cells.forEach(function(c){ row.push(csvEscapeCell(c.innerText)); });
      lines.push(row.join(','));
    });
  });
  downloadCsv(lines, 'call_center_dashboard.csv');
}

function getCellSortValue(cell){
  var t = cell.innerText.trim();
  var n = parseFloat(t.replace(/,/g,''));
  return isNaN(n) ? t : n;
}
function sortTableByColumn(table, colIndex, dir){
  var tbody = table.querySelector('tbody');
  var rows = Array.prototype.slice.call(tbody.querySelectorAll('tr'));
  rows.sort(function(r1, r2){
    var v1 = getCellSortValue(r1.children[colIndex]);
    var v2 = getCellSortValue(r2.children[colIndex]);
    if(v1 < v2) return dir === 'asc' ? -1 : 1;
    if(v1 > v2) return dir === 'asc' ? 1 : -1;
    return 0;
  });
  rows.forEach(function(r){ tbody.appendChild(r); });
}
function initSortableTables(){
  document.querySelectorAll('table.data-table').forEach(function(table){
    var ths = table.querySelectorAll('thead th');
    ths.forEach(function(th, idx){
      th.addEventListener('click', function(){
        var dir = th.classList.contains('sort-asc') ? 'desc' : 'asc';
        ths.forEach(function(t){ t.classList.remove('sort-asc','sort-desc'); });
        th.classList.add(dir === 'asc' ? 'sort-asc' : 'sort-desc');
        sortTableByColumn(table, idx, dir);
      });
    });
  });
}
initSortableTables();

function openHelpModal(){ document.getElementById('helpModalOverlay').classList.add('open'); }
function closeHelpModal(){ document.getElementById('helpModalOverlay').classList.remove('open'); }
</script>
</div>
</body>
</html>]]

